System.register("chunks:///_virtual/MonthlyCatalog.ts",[],(function(t){return{execute:function(){t("MONTHLY_CARDS",[{id:"oct-c1-1",chapter:1,name:"门前集合",rarity:1,story:"招财把小挎包背好，伙伴们已经在落叶小径旁等候。"},{id:"oct-c1-2",chapter:1,name:"口袋清单",rarity:1,story:"小狗检查口袋里的水壶，还为朋友多留了一条手帕。"},{id:"oct-c1-3",chapter:1,name:"第一片秋叶",rarity:1,story:"小鹿把落叶举到阳光下，叶脉像一张通往森林的地图。"},{id:"oct-c1-4",chapter:1,name:"系好鞋带",rarity:1,story:"小熊蹲下帮小猪系鞋带，大家说今天可以慢慢走。"},{id:"oct-c1-5",chapter:1,name:"林口路标",rarity:1,story:"猫头鹰落在旧路标上，为第一次秋游的朋友指路。"},{id:"oct-c1-6",chapter:1,name:"一起出发",rarity:2,story:"门铃轻轻响过，长长的影子把小伙伴们连成一队。"},{id:"oct-c2-1",chapter:2,name:"露珠栗壳",rarity:1,story:"刺猬在草叶间找到一颗栗子，壳上的露珠还没有醒。"},{id:"oct-c2-2",chapter:2,name:"落叶寻宝",rarity:1,story:"小兔拨开一片叶子，圆圆的栗子正安静地躲在下面。"},{id:"oct-c2-3",chapter:2,name:"软软接住",rarity:1,story:"小熊把围巾铺成小兜，接住伙伴轻轻递来的栗子。"},{id:"oct-c2-4",chapter:2,name:"一篮两份",rarity:1,story:"招财把满篮分成两份，小小的一份留给晚来的朋友。"},{id:"oct-c2-5",chapter:2,name:"栗壳小屋",rarity:2,story:"小猪把空栗壳摆成小房子，门前还铺了一条叶子路。"},{id:"oct-c2-6",chapter:2,name:"留给森林",rarity:2,story:"大家把最后几颗栗子放回树下，让明年的秋天也有香气。"},{id:"oct-c3-1",chapter:3,name:"石桥那边",rarity:1,story:"小水獭先过石桥，又回头等大家一起听溪水的声音。"},{id:"oct-c3-2",chapter:3,name:"铺开方格",rarity:1,story:"小狗拉住野餐布的一角，秋风便没能把午餐提前带走。"},{id:"oct-c3-3",chapter:3,name:"面包分你",rarity:1,story:"小猪掰开热乎乎的面包，把更蓬松的那半递给招财。"},{id:"oct-c3-4",chapter:3,name:"茶香绕过石头",rarity:2,story:"熊猫慢慢倒出热茶，白白的水汽绕过溪边的石头。"},{id:"oct-c3-5",chapter:3,name:"叶船靠岸",rarity:2,story:"小水獭用落叶折一只船，把它停在浅浅的水湾里。"},{id:"oct-c3-6",chapter:3,name:"满满一张布",rarity:2,story:"午后的阳光照着空下来的篮子，大家的心却装得很满。"},{id:"oct-c4-1",chapter:4,name:"挑一片枫红",rarity:1,story:"小狐狸挑出最完整的红叶，想把这一刻寄回小屋。"},{id:"oct-c4-2",chapter:4,name:"叶脉拓印",rarity:1,story:"小兔按住纸角，叶子的细纹慢慢留在奶油色纸上。"},{id:"oct-c4-3",chapter:4,name:"一枚栗子印",rarity:2,story:"招财把栗子壳轻轻按在信封上，留下圆圆的小记号。"},{id:"oct-c4-4",chapter:4,name:"小小邮差包",rarity:2,story:"小狗的挎包装满了落叶信，比出门时多了一点秋天。"},{id:"oct-c4-5",chapter:4,name:"山坡收信人",rarity:2,story:"猫头鹰替伙伴把信送到山坡，小考拉在门口接住夕光。"},{id:"oct-c4-6",chapter:4,name:"把秋天寄回家",rarity:3,story:"每个人都选了一种颜色，一摞小信封就拼出了整片森林。"},{id:"oct-c5-1",chapter:5,name:"影子长高了",rarity:1,story:"小鹿发现自己的影子变高了，便放慢脚步等小猪追上。"},{id:"oct-c5-2",chapter:5,name:"长椅歇一会",rarity:2,story:"小熊把篮子放下，招财在长椅上给大家腾出一点位置。"},{id:"oct-c5-3",chapter:5,name:"风里的围巾",rarity:2,story:"小狐狸给打盹的考拉搭上围巾，秋风也跟着轻了下来。"},{id:"oct-c5-4",chapter:5,name:"一起抬篮子",rarity:2,story:"两只爪子觉得有点重，四只爪子就把回家的路走轻了。"},{id:"oct-c5-5",chapter:5,name:"窗边第一盏灯",rarity:3,story:"小屋窗里亮起灯时，水獭知道最后一座小桥就在前面。"},{id:"oct-c5-6",chapter:5,name:"回头看一眼",rarity:3,story:"招财回头看了看金色树林，轻轻把今天记进心里。"},{id:"oct-c6-1",chapter:6,name:"烤栗子的香气",rarity:2,story:"小熊把烤好的栗子端到桌上，暖香先敲开了每个人的笑脸。"},{id:"oct-c6-2",chapter:6,name:"轻轻剥开",rarity:2,story:"刺猬剥开一颗栗子，把完整的那半放进朋友的小碟里。"},{id:"oct-c6-3",chapter:6,name:"给你留一碗",rarity:2,story:"招财把小碗推到门边，夜归的猫头鹰也有热乎乎的一份。"},{id:"oct-c6-4",chapter:6,name:"茶杯里的月亮",rarity:2,story:"熊猫给茶杯续上热水，圆圆的灯影像一轮小月亮。"},{id:"oct-c6-5",chapter:6,name:"把叶子夹好",rarity:3,story:"小考拉把今天的红叶夹进书里，明天翻开还会想起朋友。"},{id:"oct-c6-6",chapter:6,name:"栗香说晚安",rarity:3,story:"篮子空了，灯光低了，小屋里还留着一整天的温暖。"}])}}}));

